  // FAQ
  hero_faq_headline: 'Common questions',
  faq_q1: 'How does Homatch find buyers without a public listing?',
  faq_a1: 'Homatch scans public channels — Facebook groups, Telegram supergroups, forums, Google and Bing — for posts where people express buying or renting intent. We match those signals against your property details.',
  faq_q2: 'Is my property visible to the public?',
  faq_a2: 'No. Private listings are never published. Your address, price and photos are hidden until you choose to unlock a match.',
  faq_q3: 'What does unlocking a match reveal?',
  faq_a3: 'After unlocking, you see the full original signal text, the platform and group it came from, a direct link to the post or profile, and the AI-extracted intent details including budget, location and property type.',
  faq_q4: 'What if no matches are found?',
  faq_a4: 'You are only charged credits when you unlock a match. If no matches appear, nothing is deducted. You can pause or delete your campaign at any time.',
  faq_q5: 'Which property markets does Homatch support?',
  faq_a5: 'Homatch is currently optimized for Georgia (Tbilisi and major cities). Additional markets are planned.',

