  home_faq_title: 'Frequently Asked Questions',
  home_faq_1_q: 'What makes Homatch different from a listing portal?',
  home_faq_1_a: 'Homatch is not a listing portal. It is an AI matching platform that works for both sides: buyers/renters tell AI what they need and Homatch finds supply; sellers/landlords upload once and Homatch finds demand. We search across internal and external sources, compare duplicates and help you verify before you decide.',
  home_faq_2_q: 'How does AI property search work?',
  home_faq_2_a: 'Type or speak what you need in any language. Homatch AI interprets your requirements, searches the internal network first, then scans external sources like property portals and social groups. Results are ranked by match score, trust and freshness.',
  home_faq_3_q: 'What is the Trust Score?',
  home_faq_3_a: 'Each listing is evaluated for consistency across sources, area discrepancies, duplicate images, data freshness and cadastral match. The output is a confidence label and risk indicators — not a guarantee, but a useful signal before you commit.',
  home_faq_4_q: 'Can I verify a property before buying?',
  home_faq_4_a: 'Yes. The Verification Center lets you search by property address, cadastral code, developer name or project. You can see official records, source-reported data, AI inference and what is unavailable — clearly labeled.',
  home_faq_5_q: 'How does seller/landlord matching work?',
  home_faq_5_a: 'Add or import your property. Homatch builds a demand profile and scans internal buyers/renters first. If more demand is needed, external sources are searched. Qualified leads are ranked and previewed before you unlock contact details.',
  home_faq_6_q: 'Is Active AI Search really automatic?',
  home_faq_6_a: 'Yes. Set your criteria once and Homatch keeps running. When new matching properties or buyer signals appear, you get notified automatically — no need to check manually.',
  home_cta_title: 'Start with Homatch AI — free',
  home_cta_desc: 'Tell us what you need. We find it, match it and help you verify it.',
  home_cta_button: 'Try Homatch AI Free',

