  hero_faq_headline: 'ხშირად დასმული კითხვები',
  faq_q1: 'როგორ პოულობს Homatch მყიდველებს საჯარო განცხადების გარეშე?',
  faq_a1: 'Homatch სკანირებს საჯარო არხებს — Facebook ჯგუფები, Telegram სუპერჯგუფები, ფორუმები, Google და Bing — სადაც ადამიანები გამოხატავენ ყიდვის ან ქირაობის განზრახვას.',
  faq_q2: 'ხილული იქნება ჩემი ქონება საჯაროდ?',
  faq_a2: 'არა. კერძო განცხადებები არასოდეს ქვეყნდება. მისამართი, ფასი და ფოტოები დამალულია.',
  faq_q3: 'რას ავლენს შესატყვისის განბლოკვა?',
  faq_a3: 'განბლოკვის შემდეგ ნახავთ სრულ ორიგინალ სიგნალს, პლატფორმას, პირდაპირ ბმულს და AI-ამოღებულ დეტალებს.',
  faq_q4: 'რა მოხდება, თუ შესატყვისი ვერ მოიძებნება?',
  faq_a4: 'კრედიტები ჩამოიჭრება მხოლოდ შესატყვისის განბლოკვისას. თუ შესატყვისი ვერ გამოჩნდა, არაფერი ჩამოიჭრება.',
  faq_q5: 'რომელ ბაზრებს ემსახურება Homatch?',
