  home_why_1_desc: 'ერთი AI მოთხოვნა ერთდროულად მოიცავს Homatch-ს, უძრავი ქონების პორტალებს, Telegram-სა და Facebook-ჯგუფებს.',
  home_why_2_title: 'ჯერ შიდა მიწოდება/მოთხოვნა',
  home_why_2_desc: 'თქვენი მოთხოვნა ჯერ მოწმდება Homatch-ის ქსელთან, სანამ ნებისმიერი გარე ფასიანი ძიება ჩაირთვება.',
