  home_why_5_title: 'გადაამოწმეთ გადაწყვეტილებამდე',
  home_why_5_desc: 'საკადასტრო ჩანაწერები, საკუთრება, დეველოპერის ისტორია და რისკის სიგნალები — ყველაფერი ერთ ადგილას.',
