  faq_a3: 'Açtıktan sonra tam orijinal sinyal metnini, platformu ve grubunu, gönderi veya profile doğrudan bağlantıyı ve bütçe, konum, mülk türü dahil yapay zeka tarafından çıkarılan niyet ayrıntılarını görürsünüz.',
