  admin_providers_kill_switch_active: 'GENEL ACİL DURDURMA AKTİF — Tüm Ücretli Sağlayıcılar Engellendi',
  admin_providers_kill_switch_desc: 'Platform genelinde TÜM ücretli sağlayıcı çağrılarını engeller. Kontrolsüz harcamayı önlemek için acil durumlarda kullanın.',
